using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The MCP SDK resolves constructor parameters from the DI container.
    // HttpClient is injected via IHttpClientFactory (named client registered in Program.cs).
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool(Name = "get_weather"), Description("Get current weather for a city.")]
    public async Task<string> GetWeatherAsync(
        [Description("City name, e.g. \"Seattle\"")] string city,
        CancellationToken cancellationToken = default)
    {
        // Example using the free Open-Meteo geocoding + forecast API (no key required).
        var geoUrl = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";
        var geoJson = await _httpClient.GetFromJsonAsync<JsonElement>(geoUrl, cancellationToken);

        if (!geoJson.TryGetProperty("results", out var results) || results.GetArrayLength() == 0)
            return $"City '{city}' not found.";

        var loc = results[0];
        var lat = loc.GetProperty("latitude").GetDouble();
        var lon = loc.GetProperty("longitude").GetDouble();
        var name = loc.GetProperty("name").GetString();

        var wxUrl = $"https://api.open-meteo.com/v1/forecast?latitude={lat}&longitude={lon}&current=temperature_2m,wind_speed_10m";
        var wxJson = await _httpClient.GetFromJsonAsync<JsonElement>(wxUrl, cancellationToken);
        var current = wxJson.GetProperty("current");

        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Weather in {name}: {temp}°C, wind {wind} km/h";
    }

    [McpServerTool(Name = "get_forecast"), Description("Get multi-day forecast for a city.")]
    public async Task<string> GetForecastAsync(
        [Description("City name")] string city,
        [Description("Number of forecast days (1-7)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 7);

        var geoUrl = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1";
        var geoJson = await _httpClient.GetFromJsonAsync<JsonElement>(geoUrl, cancellationToken);

        if (!geoJson.TryGetProperty("results", out var results) || results.GetArrayLength() == 0)
            return $"City '{city}' not found.";

        var loc = results[0];
        var lat = loc.GetProperty("latitude").GetDouble();
        var lon = loc.GetProperty("longitude").GetDouble();
        var name = loc.GetProperty("name").GetString();

        var wxUrl = $"https://api.open-meteo.com/v1/forecast?latitude={lat}&longitude={lon}"
                  + $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";
        var wxJson = await _httpClient.GetFromJsonAsync<JsonElement>(wxUrl, cancellationToken);
        var daily = wxJson.GetProperty("daily");

        var dates = daily.GetProperty("time");
        var highs = daily.GetProperty("temperature_2m_max");
        var lows  = daily.GetProperty("temperature_2m_min");

        var lines = new List<string> { $"Forecast for {name} ({days} days):" };
        for (int i = 0; i < dates.GetArrayLength(); i++)
        {
            lines.Add($"  {dates[i].GetString()}: High {highs[i].GetDouble()}°C, Low {lows[i].GetDouble()}°C");
        }

        return string.Join("\n", lines);
    }
}

